#!/usr/bin/env python3
"""Regenerate the documentation pages that are derived rather than written.

Four pages under `docs/` restate something this repository already defines: the
CLI's own `--help` text, the shared language table, what each policy and layout
does to a fixed sample, and which markers survive a removal. A page like that is
stale the moment the thing it restates changes, and a stale page is worse than
no page at all, so it is generated here and `--check` fails the build when the
checked-in bytes and the regenerated bytes differ.

`--check` also compares `docs/ocomment.1` with the page `<binary> man` renders.
A Rust test pins the same file; both are kept, because that test proves the
shipped manual page still matches the parser, while this proves the
documentation site ships the page that was shipped.

Every example comes out of the built binary or out of `spec/`, never out of
prose, so nothing on the generated pages can claim behaviour the binary does not
have. Only the standard library is used, because this runs in a job that
installs nothing beyond the toolchain.
"""

from __future__ import annotations

import argparse
import difflib
import itertools
import json
import os
import pathlib
import re
import subprocess
import tempfile
import tomllib


ROOT = pathlib.Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"
LANGUAGES = ROOT / "spec/languages.toml"
DIRECTIVES = ROOT / "spec/directives.toml"
MAN_PAGE = DOCS / "ocomment.1"
DEFAULT_BINARIES = (
    ROOT / "rust/target/debug/ocomment",
    ROOT / "rust/target/release/ocomment",
)

